const tasks = $input.all();
const output = [];

for (const task of tasks) {
  const t = task.json;
  const desc = t.description || t.content || '';
  const taskId = t.id;
  const taskName = t.name || '';

  // Pull customer name from task name (format: "CustomerName - ProductDescription")
  const customerName = taskName.split(' - ')[0]?.trim() || 'Unknown';

  // Pull product description from task name
  const productDescription = taskName.split(' - ').slice(1).join(' - ').trim() || '';

  // Extract invoice number
  const invoiceMatch = desc.match(/I(\d{8})/);
  const invoiceNumber = invoiceMatch ? invoiceMatch[0] : '';

  // Extract order date (first date in description)
  const dateMatch = desc.match(/(\d{1,2}\/\d{1,2}\/\d{4})/);
  const orderDate = dateMatch ? dateMatch[0] : '';

  // Extract carrier line
  const carrierMatch = desc.match(/(UPS Ground|UPS 2 Day|FedEx Freight|FedEx)/i);
  const carrier = carrierMatch ? carrierMatch[0] : 'Unknown';

  // Extract UPS tracking numbers (1Z format)
  const upsNumbers = desc.match(/1Z[A-Z0-9]{16}/g) || [];

  // Extract FedEx Freight PRO numbers (10-12 digit standalone numbers)
  const allNumbers = desc.match(/\b\d{10,12}\b/g) || [];
  const fedexNumbers = allNumbers.filter(n => !n.startsWith('1Z'));

  // Determine which numbers to use based on carrier
  let trackingNumbers = [];
  if (carrier.toLowerCase().includes('ups')) {
    trackingNumbers = upsNumbers.map(n => ({ number: n, carrier: 'UPS' }));
  } else if (carrier.toLowerCase().includes('fedex')) {
    trackingNumbers = fedexNumbers.map(n => ({ number: n, carrier: 'FedEx Freight' }));
  } else {
    // fallback: grab whatever is there
    trackingNumbers = [
      ...upsNumbers.map(n => ({ number: n, carrier: 'UPS' })),
      ...fedexNumbers.map(n => ({ number: n, carrier: 'FedEx Freight' }))
    ];
  }

  // Extract last known status from description
  // We write it as "--- Last Status: In Transit ---" when we update
  const lastStatusMatch = desc.match(/--- Last Status: ([^-\n]+) ---/);
  const lastStatus = lastStatusMatch ? lastStatusMatch[1].trim() : null;

  for (const tracking of trackingNumbers) {
    const trackingUrl = tracking.carrier === 'UPS'
      ? `https://www.ups.com/track?tracknum=${tracking.number}`
      : `https://www.fedexfreight.com/en-us/tracking?trackingNumber=${tracking.number}`;

    output.push({
      json: {
        taskId,
        taskName,
        customerName,
        productDescription,
        invoiceNumber,
        orderDate,
        carrier: tracking.carrier,
        trackingNumber: tracking.number,
        trackingUrl,
        lastStatus,
        fullDescription: desc
      }
    });
  }
}

return output;

const item = $input.first().json;
const html = item.data || item.body || '';
const carrier = item.carrier;

let status = 'Unknown';
let delivered = false;

const h = html.toLowerCase();

if (carrier === 'UPS') {
  if (h.includes('delivered')) {
    status = 'Delivered';
    delivered = true;
  } else if (h.includes('out for delivery')) {
    status = 'Out for Delivery';
  } else if (h.includes('on the way') || h.includes('in transit')) {
    status = 'In Transit';
  } else if (h.includes('departed')) {
    status = 'In Transit - Departed Facility';
  } else if (h.includes('arrived')) {
    status = 'In Transit - Arrived at Facility';
  } else if (h.includes('picked up') || h.includes('pickup')) {
    status = 'Picked Up';
  } else if (h.includes('label created') || h.includes('shipment information')) {
    status = 'Label Created';
  } else if (h.includes('exception') || h.includes('delay')) {
    status = 'Delay / Exception';
  }
} else {
  // FedEx Freight
  if (h.includes('delivered')) {
    status = 'Delivered';
    delivered = true;
  } else if (h.includes('out for delivery') || h.includes('on fedex vehicle')) {
    status = 'Out for Delivery';
  } else if (h.includes('in transit') || h.includes('in-transit')) {
    status = 'In Transit';
  } else if (h.includes('at local') || h.includes('at destination')) {
    status = 'At Local Facility';
  } else if (h.includes('picked up')) {
    status = 'Picked Up';
  } else if (h.includes('shipment information sent') || h.includes('label created')) {
    status = 'Label Created';
  } else if (h.includes('exception') || h.includes('delay')) {
    status = 'Delay / Exception';
  }
}

const now = new Date().toLocaleString('en-US', {
  timeZone: 'America/New_York',
  month: '2-digit',
  day: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  hour12: true
});

const statusChanged = item.lastStatus !== status;
const isFirstSeen = !item.lastStatus;

return [{
  json: {
    ...item,
    currentStatus: status,
    delivered,
    statusChanged,
    isFirstSeen,
    checkedAt: now
  }
}];

